# Let me test simple replacements to see what works
inputs = ['aizz', 'hxzc', 'zhja', 'bkfuf', 'ixeacu']
outputs = ['adzz', 'avxzc', 'zavja', 'zgffdfuf', 'dxeacu']

print("Input -> Output")
for i, inp in enumerate(inputs):
    print(f"'{inp}' -> '{outputs[i]}'")

# Let me try to identify patterns by checking what changes
print("\nPattern analysis:")
for i, inp in enumerate(inputs):
    out = outputs[i]
    print(f"{inp} -> {out}")
    # Show differences
    for j, (in_char, out_char) in enumerate(zip(inp, out)):
        if in_char != out_char:
            print(f"  Position {j}: '{in_char}' -> '{out_char}'")
    if len(out) > len(inp):
        print(f"  Length increased from {len(inp)} to {len(out)}")
    elif len(out) < len(inp):
        print(f"  Length decreased from {len(inp)} to {len(out)}")

